<template>
  <v-app>
    <AppLayout>
      <router-view />
    </AppLayout>
  </v-app>
</template>

<script setup>
import { onMounted, onUnmounted } from "vue";
import AppLayout from "@/layouts/AppLayout.vue";

// 現在読み込まれているJSバンドルのファイル名を取得
function getCurrentBundleId() {
  const scripts = document.querySelectorAll("script[src]");
  for (const s of scripts) {
    if (s.src.includes("/js/app.")) return s.src;
  }
  return null;
}

// index.html をキャッシュなしで取得し、JSバンドルが変わっていたらリロード
async function checkForUpdate() {
  try {
    const currentSrc = getCurrentBundleId();
    if (!currentSrc) return;
    const currentFile = currentSrc.split("/").pop(); // 例: app.abc123.js

    const res = await fetch("./index.html?_=" + Date.now(), {
      cache: "no-store",
    });
    const html = await res.text();

    if (!html.includes(currentFile)) {
      window.location.reload();
    }
  } catch {
    // ネットワークエラー等は無視
  }
}

let intervalId = null;

function onVisibilityChange() {
  if (document.visibilityState === "visible") checkForUpdate();
}

onMounted(() => {
  // タブを再表示したタイミングでチェック
  document.addEventListener("visibilitychange", onVisibilityChange);
  // 5分ごとにもチェック
  intervalId = setInterval(checkForUpdate, 5 * 60 * 1000);
});

onUnmounted(() => {
  document.removeEventListener("visibilitychange", onVisibilityChange);
  clearInterval(intervalId);
});
</script>

